KG_CODE("f:src/autoskill/desktop/overlay.py","\"\"\"Agent cursor overlay: a visible marker for what the tool is doing.\n\nWhen the agent acts on the user's desktop, the user should be able to *see*\nit. The cuabot arrow (#1A8E88) follows its original wind path and fade timing.\nThe screen-edge glow is #20B2AA; the existing status pill is unchanged.\n\nHard rules that shape the code:\n\n* **Fail-open.** The overlay is decoration. Any Win32 error, at any point,\n  must degrade to \"no overlay\", never to a failed action. Every public entry\n  point swallows every exception; the automation path pays at most one\n  capped (~0.3 s) arrival wait.\n* **Click-through and focus-neutral.** The windows are\n  ``WS_EX_TRANSPARENT | WS_EX_LAYERED | WS_EX_NOACTIVATE | WS_EX_TOOLWINDOW``\n  and topmost: the mouse passes through them, they never take focus or\n  activation, and they do not appear in the taskbar or Alt-Tab.\n* **Own thread, own message loop.** All Win32 contact happens on a single\n  daemon thread fed by a thread-safe command queue, so the overlay never\n  blocks or races the UIA worker that drives real actions.\n* **Self-exclusion.** ``hidden_for_capture()`` hides the overlay while\n  autoskill takes its own screenshots, so the marker never photographs\n  itself.\n* **DPI.** The process runs DPI-unaware (nothing in autoskill sets DPI\n  awareness, and UIA ``BoundingRectangle``, ``GetSystemMetrics`` and\n  ``mss`` all report in the same virtualised coordinate space). The overlay\n  deliberately does NOT call ``SetProcessDPIAware``: it lives in exactly\n  the coordinate space ``actions.py`` already works in.\n\n``ctypes`` (user32/gdi32) plus the existing Pillow image dependency. Rendering\nis per-pixel alpha — each window owns a 32-bpp BGRA DIB uploaded with\n``UpdateLayeredWindow`` (``ULW_ALPHA``), the same pipeline cua-driver uses\n(tiny-skia → BGRA DIB → UpdateLayeredWindow). Shape lives in the pixels'\nalpha channel; fades ride the blend's ``SourceConstantAlpha``, so a fade\nre-uploads the same bitmap with a different constant and the pixel buffer\nis built exactly once per window. (The first version of this module used a\nmagenta colour-key plus ``LWA_ALPHA``; it never painted — ``FillRect`` was\ncalled on gdi32, where it does not exist — and colour-key rendering looks\njagged anyway. Per-pixel alpha is both correct and smoother.)\n\nDisable with ``AUTOSKILL_OVERLAY=off``.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport atexit\nimport base64\nimport math\nimport random\nfrom functools import lru_cache\nimport ctypes\nimport json\nimport os\nimport queue\nimport threading\nimport time\nfrom contextlib import contextmanager\nfrom pathlib import Path\nfrom typing import Any\n\n# Read once at import: the convention in this codebase for behaviour\n# switches is an environment variable (cf. AUTOSKILL_IDLE_TIMEOUT).\nENABLED = os.environ.get(\"AUTOSKILL_OVERLAY\", \"on\").strip().lower() not in (\n    \"off\", \"0\", \"false\", \"no\", \"disabled\")\n\n# --- tuning ------------------------------------------------------------------\n\nCURSOR_SIZE = 32                  # px, square window; hotspot at its upper-left origin\nGLIDE_MS = 100                    # nominal glide duration to a new target\nARRIVAL_WAIT_S = 0.30             # cap: a wedged overlay never delays input\nIDLE_FADE_S = 15.0                 # hide the cursor after this much silence\nPULSE_ALPHA = 255                 # alpha right at the pulse\nREST_ALPHA = 255                  # alpha the cursor rests at\nPULSE_DECAY_PER_S = 320           # pulse fade speed\nGLOW_ALPHA = 150                  # translucent sky blue, at flash peak\nGLOW_DECAY_PER_S = 380            # glow fade speed (~0.4 s total)\nGLOW_BORDER_PX = 12               # edge-glow stroke thickness\nTICK_S = 0.016                    # cuabot animation tick\n\nDESKTOP_GREEN = (0x5E, 0xC5, 0x22)  # #22c55e in BGRA byte order\nCURSOR_BGR = (0x88, 0x8E, 0x1A)  # #1A8E88\nGLOW_BGR = (0xAA, 0xB2, 0x20)  # #20B2AA\nSKY_BLUE = DESKTOP_GREEN  # compatibility name for existing renderer clients\n\n# --- the bar (status pill) ---------------------------------------------------\n#\n# The cursor shows *where*; the bar says *what*. One shared state vocabulary\n# drives both this desktop bar and the browser extension's in-page bar, so\n# the two surfaces always speak the same language (S153).\n\nBAR_W = 460                     # px, pill centred top-of-screen\nBAR_H = 48\nBAR_TOP = 24                    # px below the virtual-screen top edge\nBAR_REST_ALPHA = 235            # pill opacity once settled\nBAR_FADE_IN_PER_S = 900         # appear fast: the user is waiting\nBAR_FADE_OUT_PER_S = 420        # leave gently\nBAR_IDLE_S = 3.5                # hide after this much silence\n\n# State -> accent colour (BGR), shared with the browser toolbar.\nSTATE_COLORS = {\n    \"aiming\":    DESKTOP_GREEN,\n    \"acting\":    DESKTOP_GREEN,\n    \"verifying\": (0x24, 0xBF, 0xFB),   # amber      — checking the effect\n    \"done\":      (0x99, 0xD3, 0x34),   # green      — committed\n    \"stuck\":     (0x71, 0x71, 0xF8),   # red        — needs attention\n    \"approval\":  (0xFA, 0x8B, 0xA7),   # violet     — waiting on the human\n}\nBAR_BG = (0x2A, 0x17, 0x0F)           # slate #0f172a (BGR)\nBAR_TEXT = (0xEB, 0xE7, 0xE5)         # near-white #e5e7eb (BGR)\n\n\n# Cursor asset and wind path adapted from cuabot (MIT; native/overlay/CUA-LICENSE.md).\ndef generate_path(from_pos: tuple, to_pos: tuple, target_steps: int = 20) -> list:\n    \"\"\"Generate a human-like mouse path with gravity and wind forces.\"\"\"\n    s3 = math.sqrt(3)\n    s5 = math.sqrt(5)\n\n    gravity = 9.0\n    wind = 3.0\n    max_v = 15.0\n    damp_dist = 12.0\n\n    x, y = float(from_pos[0]), float(from_pos[1])\n    dx, dy = float(to_pos[0]), float(to_pos[1])\n\n    vx = vy = 0.0\n    wx = wy = 0.0\n    mv = max_v\n\n    path = [(x, y)]\n\n    for _ in range(500):\n        dist = math.hypot(dx - x, dy - y)\n        if dist < 1:\n            break\n\n        wm = min(wind, dist)\n\n        if dist >= damp_dist:\n            wx = wx / s3 + (2 * random.random() - 1) * wm / s5\n            wy = wy / s3 + (2 * random.random() - 1) * wm / s5\n        else:\n            wx /= s3\n            wy /= s3\n            if mv < 3:\n                mv = random.random() * 3 + 3\n            else:\n                mv /= s5\n\n        vx += wx + gravity * (dx - x) / dist\n        vy += wy + gravity * (dy - y) / dist\n\n        vm = math.hypot(vx, vy)\n        if vm > mv:\n            vc = mv / 2 + random.random() * mv / 2\n            vx = (vx / vm) * vc\n            vy = (vy / vm) * vc\n\n        x += vx\n        y += vy\n        path.append((x, y))\n\n    path.append((dx, dy))\n\n    if len(path) > target_steps:\n        idx = [int(i * (len(path) - 1) / target_steps) for i in range(target_steps + 1)]\n        path = [path[i] for i in idx]\n\n    return path\n\n@lru_cache(maxsize=1)\ndef cursor_pixels() -> bytes:\n    \"\"\"Original grayscale arrow, aspect preserved, tinted and premultiplied BGRA.\"\"\"\n    from PIL import Image\n    from ..resources import asset\n    with Image.open(asset(\"native/overlay/cursor.png\")) as source:\n        sprite = source.convert(\"RGBA\")\n        sprite.thumbnail((CURSOR_SIZE, CURSOR_SIZE), Image.Resampling.BILINEAR)\n        canvas = Image.new(\"RGBA\", (CURSOR_SIZE, CURSOR_SIZE))\n        canvas.paste(sprite, (0, 0))\n        rgba = canvas.tobytes()\n    data = bytearray(len(rgba))\n    for i in range(0, len(rgba), 4):\n        intensity, alpha = rgba[i], rgba[i+3]\n        data[i:i+4] = bytes((*[round(c * intensity * alpha / 65025)\n                              for c in CURSOR_BGR], alpha))\n    return bytes(data)\n\n\n# --- Win32 layer -------------------------------------------------------------\n#\n# Everything that touches ctypes lives in Win32Backend. Tests substitute a\n# fake backend and drive AgentCursorOverlay._tick() by hand, so no real\n# window is ever created outside production.\n\nclass Win32Backend:\n    \"\"\"Thin ctypes wrapper around the two layered windows.\n\n    Two windows, both ``WS_POPUP`` with extended style\n    ``WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_TOPMOST | WS_EX_NOACTIVATE\n    | WS_EX_TOOLWINDOW``:\n\n    * the **cursor** — a small ring that follows the action target;\n    * the **glow** — a full-virtual-screen frame with a sky-blue border,\n      flashed once when the agent starts acting after idle.\n\n    Each window is backed by a top-down 32-bpp BGRA DIB section uploaded\n    with ``UpdateLayeredWindow``. Buffers are filled once at start; later\n    alpha changes only re-upload with a new ``SourceConstantAlpha``.\n    \"\"\"\n\n    WS_POPUP = 0x80000000\n    WS_EX_TOPMOST = 0x00000008\n    WS_EX_TRANSPARENT = 0x00000020\n    WS_EX_LAYERED = 0x00080000\n    WS_EX_TOOLWINDOW = 0x00000080\n    WS_EX_NOACTIVATE = 0x08000000\n\n    SW_HIDE = 0\n    SW_SHOWNA = 8                   # show without activating\n\n    SWP_NOSIZE = 0x0001\n    SWP_NOMOVE = 0x0002\n    SWP_NOZORDER = 0x0004\n    SWP_NOACTIVATE = 0x0010\n\n    ULW_ALPHA = 0x00000002\n    AC_SRC_OVER = 0x00\n    AC_SRC_ALPHA = 0x01\n    BI_RGB = 0\n    DIB_RGB_COLORS = 0\n\n    PM_REMOVE = 0x0001\n    HWND_TOPMOST = -1\n\n    def __init__(self) -> None:\n        import ctypes\n        import ctypes.wintypes as wt\n        self._ct = ctypes\n        self._wt = wt\n        self.user32 = ctypes.windll.user32\n        self.gdi32 = ctypes.windll.gdi32\n        self.kernel32 = ctypes.windll.kernel32\n        # ctypes.windll functions default to c_int for every argument and the\n        # return value; window messages carry pointer-sized WPARAM/LPARAM and\n        # overflow that on Win64 (measured: ArgumentError in the wndproc).\n        u, g = self.user32, self.gdi32\n        u.DefWindowProcW.restype = ctypes.c_ssize_t\n        u.DefWindowProcW.argtypes = [wt.HWND, wt.UINT,\n                                     ctypes.c_size_t, ctypes.c_ssize_t]\n        # Handles are pointer-sized on Win64; without these declarations\n        # ctypes truncates them to c_int (measured: OverflowError in\n        # SelectObject when a DIB handle lands above 2**31).\n        u.CreateWindowExW.restype = wt.HWND\n        u.SetWindowPos.argtypes = [wt.HWND, wt.HWND] + [ctypes.c_int] * 4 + [wt.UINT]\n        u.ShowWindow.argtypes = [wt.HWND, ctypes.c_int]\n        u.DestroyWindow.argtypes = [wt.HWND]\n        u.UpdateLayeredWindow.argtypes = [\n            wt.HWND, wt.HDC, ctypes.c_void_p, ctypes.c_void_p, wt.HDC,\n            ctypes.c_void_p, wt.DWORD, ctypes.c_void_p, wt.DWORD]\n        g.CreateCompatibleDC.restype = wt.HDC\n        g.CreateCompatibleDC.argtypes = [wt.HDC]\n        g.CreateDIBSection.restype = wt.HBITMAP\n        g.CreateDIBSection.argtypes = [\n            wt.HDC, ctypes.c_void_p, wt.UINT,\n            ctypes.POINTER(ctypes.c_void_p), wt.HANDLE, wt.DWORD]\n        g.SelectObject.restype = wt.HGDIOBJ\n        g.SelectObject.argtypes = [wt.HDC, wt.HGDIOBJ]\n        g.DeleteObject.argtypes = [wt.HGDIOBJ]\n        g.DeleteDC.argtypes = [wt.HDC]\n        # The bar paints text with GDI on a side bitmap.\n        g.CreateFontW.restype = wt.HANDLE\n        u.DrawTextW.argtypes = [wt.HDC, wt.LPCWSTR, ctypes.c_int,\n                                ctypes.c_void_p, wt.UINT]\n        g.SetBkMode.argtypes = [wt.HDC, ctypes.c_int]   # SetBkMode: gdi32\n        g.SetTextColor.argtypes = [wt.HDC, wt.DWORD]\n        # Capture exclusion (cua-driver lesson, S153): the overlay is for\n        # the human's eyes only — WDA_EXCLUDEFROMCAPTURE keeps it out of\n        # every screenshot and screen recording, including our own.\n        try:\n            u.SetWindowDisplayAffinity.argtypes = [wt.HWND, wt.DWORD]\n            self._display_affinity: Any = u.SetWindowDisplayAffinity\n        except AttributeError:               # very old Windows: degrade\n            self._display_affinity = None\n        self._class_name = \"AutoskillAgentOverlay\"\n        self._registered = False\n        self._wndproc = None        # keep the callback alive\n        self.cursor_hwnd = 0\n        self.glow_hwnd = 0\n        self.bar_hwnd = 0\n        self._cursor_surf: tuple | None = None    # (memdc, hbm, old_obj, buffer, w, h)\n        self._glow_surf: tuple | None = None\n        self._bar_surf: tuple | None = None\n        self._bar_pill: dict[str, bytes] = {}   # state -> cached pill bitmap\n        self._bar_text = \"\"\n        self._bar_state = \"acting\"\n        self._cursor_on = False\n        self._glow_on = False\n        self._bar_on = False\n        self._cursor_alpha = REST_ALPHA\n        self._glow_alpha = 0\n        self._bar_alpha = 0\n\n    # -- setup ----------------------------------------------------------------\n\n    def _register_class(self) -> None:\n        ct, wt = self._ct, self._wt\n        if self._registered:\n            return\n\n        WNDPROC = ct.WINFUNCTYPE(ct.c_ssize_t, wt.HWND, wt.UINT,\n                                 ct.c_size_t, ct.c_ssize_t)\n\n        def _proc(hwnd, msg, wparam, lparam):\n            # Nothing to paint ourselves: UpdateLayeredWindow hands the\n            # bitmap to the DWM, which composites it directly.\n            return self.user32.DefWindowProcW(hwnd, msg, wparam, lparam)\n\n        self._wndproc = WNDPROC(_proc)\n\n        class WNDCLASSEXW(ctypes.Structure):\n            _fields_ = [(\"cbSize\", wt.UINT), (\"style\", wt.UINT),\n                        (\"lpfnWndProc\", ct.c_void_p),\n                        (\"cbClsExtra\", ct.c_int), (\"cbWndExtra\", ct.c_int),\n                        (\"hInstance\", wt.HINSTANCE), (\"hIcon\", wt.HICON),\n                        (\"hCursor\", wt.HANDLE), (\"hbrBackground\", wt.HBRUSH),\n                        (\"lpszMenuName\", wt.LPCWSTR),\n                        (\"lpszClassName\", wt.LPCWSTR),\n                        (\"hIconSm\", wt.HICON)]\n\n        wc = WNDCLASSEXW()\n        wc.cbSize = ct.sizeof(WNDCLASSEXW)\n        wc.lpfnWndProc = ct.cast(self._wndproc, ct.c_void_p)\n        wc.hInstance = self.kernel32.GetModuleHandleW(None)\n        wc.lpszClassName = self._class_name\n        wc.hbrBackground = 0\n        if not self.user32.RegisterClassExW(ct.byref(wc)):\n            err = self.kernel32.GetLastError()\n            if err != 1410:                 # ERROR_CLASS_ALREADY_EXISTS\n                raise OSError(f\"RegisterClassExW failed (error {err})\")\n        self._registered = True\n\n    def _make_window(self, width: int, height: int) -> int:\n        ex = (self.WS_EX_LAYERED | self.WS_EX_TRANSPARENT | self.WS_EX_TOPMOST\n              | self.WS_EX_NOACTIVATE | self.WS_EX_TOOLWINDOW)\n        hwnd = self.user32.CreateWindowExW(\n            ex, self._class_name, \"autoskill-overlay\", self.WS_POPUP,\n            0, 0, width, height, None, None,\n            self.kernel32.GetModuleHandleW(None), None)\n        if not hwnd:\n            raise OSError(\"CreateWindowExW failed\")\n        # Excluded from capture: screenshots (ours or the user's) never\n        # photograph the marker. Fails only on ancient Windows — ignore.\n        if self._display_affinity is not None:\n            try:\n                self._display_affinity(hwnd, 0x11)   # WDA_EXCLUDEFROMCAPTURE\n            except Exception:\n                pass\n        return int(hwnd)\n\n    def _new_surface(self, hwnd: int, w: int, h: int) -> tuple:\n        \"\"\"A 32-bpp top-down BGRA DIB + memory DC for one layered window.\"\"\"\n        ct = self._ct\n\n        class BITMAPINFOHEADER(ctypes.Structure):\n            _fields_ = [(\"biSize\", ct.c_uint32), (\"biWidth\", ct.c_int32),\n                        (\"biHeight\", ct.c_int32), (\"biPlanes\", ct.c_uint16),\n                        (\"biBitCount\", ct.c_uint16),\n                        (\"biCompression\", ct.c_uint32),\n                        (\"biSizeImage\", ct.c_uint32),\n                        (\"biXPelsPerMeter\", ct.c_int32),\n                        (\"biYPelsPerMeter\", ct.c_int32),\n                        (\"biClrUsed\", ct.c_uint32),\n                        (\"biClrImportant\", ct.c_uint32)]\n\n        memdc = self.gdi32.CreateCompatibleDC(None)\n        if not memdc:\n            raise OSError(\"CreateCompatibleDC failed\")\n        bmi = BITMAPINFOHEADER()\n        bmi.biSize = ct.sizeof(BITMAPINFOHEADER)\n        bmi.biWidth = w\n        bmi.biHeight = -h                     # negative: top-down rows\n        bmi.biPlanes = 1\n        bmi.biBitCount = 32\n        bmi.biCompression = self.BI_RGB\n        bits = ct.c_void_p()\n        hbm = self.gdi32.CreateDIBSection(\n            memdc, ct.byref(bmi), self.DIB_RGB_COLORS, ct.byref(bits), None, 0)\n        if not hbm or not bits.value:\n            self.gdi32.DeleteDC(memdc)\n            raise OSError(\"CreateDIBSection failed\")\n        old = self.gdi32.SelectObject(memdc, hbm)\n        buf = (ct.c_byte * (w * h * 4)).from_address(bits.value)\n        return (memdc, hbm, old, buf, w, h)\n\n    def _free_surface(self, surf: tuple) -> None:\n        memdc, hbm, old, _buf, _w, _h = surf\n        g = self.gdi32\n        if old:\n            g.SelectObject(memdc, old)\n        if hbm:\n            g.DeleteObject(hbm)\n        if memdc:\n            g.DeleteDC(memdc)\n\n    # -- bitmaps (built once) ---------------------------------------------------\n\n    def _fill_cursor(self, surf: tuple) -> None:\n        \"\"\"The same premultiplied arrow bitmap used by the WPF renderer.\"\"\"\n        _memdc, _hbm, _old, buf, _w, _h = surf\n        buf[:] = cursor_pixels()\n\n    def _fill_glow(self, surf: tuple) -> None:\n        \"\"\"A sky-blue border at the screen edge; the interior stays at\n        alpha 0, so only the frame is visible.\"\"\"\n        _memdc, _hbm, _old, buf, w, h = surf\n        px = bytes((*GLOW_BGR, 0xFF))\n        t = max(1, min(GLOW_BORDER_PX, min(w, h) // 2))\n        data = bytearray(w * h * 4)\n        full_row = px * w\n        side = px * t\n        stride = w * 4\n        for y in range(t):                             # top band\n            data[y * stride:(y + 1) * stride] = full_row\n        for y in range(h - t, h):                      # bottom band\n            data[y * stride:(y + 1) * stride] = full_row\n        for y in range(t, h - t):                      # side columns\n            base = y * stride\n            data[base:base + t * 4] = side\n            data[base + (w - t) * 4:base + stride] = side\n        buf[:] = data\n\n    # -- the bar ----------------------------------------------------------------\n\n    def _pill(self, state: str) -> bytes:\n        \"\"\"The rounded pill background for a state, cached per state —\n        rebuilding it per text change would redo 22k pixels of capsule\n        geometry for nothing.\"\"\"\n        if state in self._bar_pill:\n            return self._bar_pill[state]\n        accent = STATE_COLORS.get(state, STATE_COLORS[\"acting\"])\n        w, h = BAR_W, BAR_H\n        r = h // 2                            # fully rounded ends\n        data = bytearray(w * h * 4)\n        bg = bytes((BAR_BG[0], BAR_BG[1], BAR_BG[2], 215))\n        edge = bytes((accent[0], accent[1], accent[2], 255))\n        cx_left, cx_right = r, w - r - 1\n        for y in range(h):\n            for x in range(w):\n                cx = min(max(x, cx_left), cx_right)\n                d = ((x - cx) ** 2 + (y - r) ** 2) ** 0.5\n                if d > r:\n                    continue\n                i = (y * w + x) * 4\n                # 2px accent rim, dark body inside\n                data[i:i + 4] = edge if d >= r - 2 else bg\n        dot = bytes((accent[0], accent[1], accent[2], 255))\n        for y in range(h):                    # state dot at (30, centre)\n            for x in range(16, 45):\n                if (x - 30) ** 2 + (y - h // 2) ** 2 <= 49:\n                    i = (y * w + x) * 4\n                    data[i:i + 4] = dot\n        self._bar_pill[state] = bytes(data)\n        return self._bar_pill[state]\n\n    def _render_bar(self) -> None:\n        \"\"\"Pill (cached) + narration text, composited into the DIB.\"\"\"\n        if self._bar_surf is None:\n            return\n        _memdc, _hbm, _old, buf, w, h = self._bar_surf\n        data = bytearray(self._pill(self._bar_state))\n        if self._bar_text:\n            try:\n                self._composite_text(data, self._bar_text, w, h)\n            except Exception:\n                # CM-52: the GDI text compositor can raise in sessions where\n                # the side-bitmap comes back short (byte-out-of-range on the\n                # blend). The box and state dot still render; the narration\n                # text also rides the indicator pointer's pill (PIL), so the\n                # user never loses the status. Fail-open, like the overlay.\n                pass\n        buf[:] = data\n\n    def _composite_text(self, data: bytearray, text: str,\n                        w: int, h: int) -> None:\n        \"\"\"GDI cannot write per-pixel alpha, so the narration is rendered\n        white-on-black on a side bitmap and blended in with luminance as\n        coverage — the classic premultiplied 'over'.\"\"\"\n        ct, g, u = self._ct, self.gdi32, self.user32\n        off = 48                                # text starts right of the dot\n        surf = self._new_surface(0, w - off - 12, h)\n        tmemdc, _thbm, _told, tbuf, tw, th = surf\n        font = None\n        try:\n            font = g.CreateFontW(-18, 0, 0, 0, 400, 0, 0, 0, 1,\n                                 0, 0, 0, 0, \"Segoe UI\")\n            oldf = g.SelectObject(tmemdc, font)\n            g.SetTextColor(tmemdc, 0x00FFFFFF)\n            g.SetBkMode(tmemdc, 1)              # TRANSPARENT\n\n            class RECT(ctypes.Structure):\n                _fields_ = [(\"left\", ct.c_long), (\"top\", ct.c_long),\n                            (\"right\", ct.c_long), (\"bottom\", ct.c_long)]\n\n            rc = RECT(0, 0, tw, th)\n            u.DrawTextW(tmemdc, text, -1, ct.byref(rc),\n                        0x4 | 0x20 | 0x8000 | 0x800)  # VCENTER|SINGLELINE|\n                                                      # END_ELLIPSIS|NOPREFIX\n            tb, tg_, tr = BAR_TEXT\n            for y in range(th):\n                base_t = y * tw * 4\n                base_d = (y * w + off) * 4\n                for x in range(tw):\n                    lum = tbuf[base_t + x * 4]   # white text: any channel\n                    if lum == 0:\n                        continue\n                    i = base_d + x * 4\n                    inv = 255 - lum\n                    data[i] = (tb * lum + data[i] * inv) // 255\n                    data[i + 1] = (tg_ * lum + data[i + 1] * inv) // 255\n                    data[i + 2] = (tr * lum + data[i + 2] * inv) // 255\n                    data[i + 3] = min(255, lum + data[i + 3] * inv // 255)\n            g.SelectObject(tmemdc, oldf)\n        finally:\n            if font:\n                g.DeleteObject(font)\n            self._free_surface(surf)\n\n    # -- upload -----------------------------------------------------------------\n\n    def _upload(self, hwnd: int, surf: tuple | None, alpha: float) -> None:\n        \"\"\"(Re)upload the DIB with a fresh SourceConstantAlpha. The pixel\n        buffer is untouched — the fade rides the blend constant.\"\"\"\n        if surf is None:\n            return\n        ct = self._ct\n        memdc, _hbm, _old, _buf, w, h = surf\n\n        class SIZE(ctypes.Structure):\n            _fields_ = [(\"cx\", ct.c_long), (\"cy\", ct.c_long)]\n\n        class POINT(ctypes.Structure):\n            _fields_ = [(\"x\", ct.c_long), (\"y\", ct.c_long)]\n\n        class BLENDFUNCTION(ctypes.Structure):\n            _fields_ = [(\"BlendOp\", ct.c_byte), (\"BlendFlags\", ct.c_byte),\n                        (\"SourceConstantAlpha\", ct.c_byte),\n                        (\"AlphaFormat\", ct.c_byte)]\n\n        blend = BLENDFUNCTION(self.AC_SRC_OVER, 0,\n                              max(0, min(255, int(alpha))), self.AC_SRC_ALPHA)\n        self.user32.UpdateLayeredWindow(\n            hwnd, None, None, ct.byref(SIZE(w, h)), memdc,\n            ct.byref(POINT(0, 0)), 0, ct.byref(blend), self.ULW_ALPHA)\n\n    def _topmost(self, hwnd: int) -> None:\n        self.user32.SetWindowPos(\n            hwnd, self.HWND_TOPMOST, 0, 0, 0, 0,\n            self.SWP_NOMOVE | self.SWP_NOSIZE | self.SWP_NOACTIVATE)\n\n    # -- lifecycle --------------------------------------------------------------\n\n    def start(self) -> None:\n        \"\"\"Create both windows and their bitmaps. Called on the overlay\n        thread. May raise — the overlay treats any failure as 'no overlay'.\"\"\"\n        self._register_class()\n        self.cursor_hwnd = self._make_window(CURSOR_SIZE, CURSOR_SIZE)\n        left, top, right, bottom = self.virtual_screen()\n        w, h = right - left, bottom - top\n        self.glow_hwnd = self._make_window(w, h)\n        self.user32.SetWindowPos(\n            self.glow_hwnd, 0, left, top, 0, 0,\n            self.SWP_NOSIZE | self.SWP_NOZORDER | self.SWP_NOACTIVATE)\n        self._cursor_surf = self._new_surface(\n            self.cursor_hwnd, CURSOR_SIZE, CURSOR_SIZE)\n        self._fill_cursor(self._cursor_surf)\n        self._glow_surf = self._new_surface(self.glow_hwnd, w, h)\n        self._fill_glow(self._glow_surf)\n        # The bar: a pill centred at the top of the virtual screen.\n        self.bar_hwnd = self._make_window(BAR_W, BAR_H)\n        self.user32.SetWindowPos(\n            self.bar_hwnd, 0, left + (w - BAR_W) // 2, top + BAR_TOP, 0, 0,\n            self.SWP_NOSIZE | self.SWP_NOZORDER | self.SWP_NOACTIVATE)\n        self._bar_surf = self._new_surface(self.bar_hwnd, BAR_W, BAR_H)\n        self._render_bar()\n        # Pre-upload so the first show is a single ShowWindow away.\n        self._upload(self.cursor_hwnd, self._cursor_surf, self._cursor_alpha)\n        self._upload(self.glow_hwnd, self._glow_surf, 0)\n        self._upload(self.bar_hwnd, self._bar_surf, 0)\n        # All start hidden; the command loop shows them on demand.\n\n    def stop(self) -> None:\n        for hwnd in (self.cursor_hwnd, self.glow_hwnd, self.bar_hwnd):\n            if hwnd:\n                self.user32.DestroyWindow(hwnd)\n        self.cursor_hwnd = self.glow_hwnd = self.bar_hwnd = 0\n        for surf in (self._cursor_surf, self._glow_surf, self._bar_surf):\n            if surf is not None:\n                self._free_surface(surf)\n        self._cursor_surf = self._glow_surf = self._bar_surf = None\n        self._bar_pill.clear()\n\n    # -- operations used by the command loop -----------------------------------\n\n    def virtual_screen(self) -> tuple[int, int, int, int]:\n        u = self.user32\n        left, top = u.GetSystemMetrics(76), u.GetSystemMetrics(77)\n        width, height = u.GetSystemMetrics(78), u.GetSystemMetrics(79)\n        return left, top, left + width, top + height\n\n    def place_cursor(self, x: float, y: float) -> None:\n        \"\"\"Centre the cursor window on (x, y). A pure move: the bitmap is\n        already with the DWM, so no re-upload is needed.\"\"\"\n        self.user32.SetWindowPos(\n            self.cursor_hwnd, 0,\n            int(x), int(y), 0, 0,\n            self.SWP_NOSIZE | self.SWP_NOZORDER | self.SWP_NOACTIVATE)\n\n    def show_cursor(self, on: bool) -> None:\n        self._cursor_on = bool(on)\n        self.user32.ShowWindow(self.cursor_hwnd,\n                               self.SW_SHOWNA if on else self.SW_HIDE)\n        if on:\n            self._topmost(self.cursor_hwnd)\n            self._upload(self.cursor_hwnd, self._cursor_surf,\n                         self._cursor_alpha)\n\n    def set_cursor_alpha(self, alpha: int) -> None:\n        self._cursor_alpha = max(0, min(255, int(alpha)))\n        if self._cursor_on and self._cursor_surf is not None:\n            self._upload(self.cursor_hwnd, self._cursor_surf,\n                         self._cursor_alpha)\n\n    def show_glow(self, on: bool) -> None:\n        self._glow_on = bool(on)\n        self.user32.ShowWindow(self.glow_hwnd,\n                               self.SW_SHOWNA if on else self.SW_HIDE)\n        if on:\n            self._topmost(self.glow_hwnd)\n            self._upload(self.glow_hwnd, self._glow_surf, self._glow_alpha)\n\n    def set_glow_alpha(self, alpha: int) -> None:\n        self._glow_alpha = max(0, min(255, int(alpha)))\n        if self._glow_on and self._glow_surf is not None:\n            self._upload(self.glow_hwnd, self._glow_surf, self._glow_alpha)\n\n    def show_bar(self, on: bool) -> None:\n        self._bar_on = bool(on)\n        self.user32.ShowWindow(self.bar_hwnd,\n                               self.SW_SHOWNA if on else self.SW_HIDE)\n        if on:\n            self._topmost(self.bar_hwnd)\n            self._upload(self.bar_hwnd, self._bar_surf, self._bar_alpha)\n\n    def set_bar(self, text: str, state: str) -> None:\n        \"\"\"New narration and/or state. Re-renders only on change; the pill\n        bitmap itself is cached per state.\"\"\"\n        state = state if state in STATE_COLORS else \"acting\"\n        if text == self._bar_text and state == self._bar_state:\n            return\n        self._bar_text = text\n        self._bar_state = state\n        self._render_bar()\n        if self._bar_on and self._bar_surf is not None:\n            self._upload(self.bar_hwnd, self._bar_surf, self._bar_alpha)\n\n    def set_bar_alpha(self, alpha: int) -> None:\n        self._bar_alpha = max(0, min(255, int(alpha)))\n        if self._bar_on and self._bar_surf is not None:\n            self._upload(self.bar_hwnd, self._bar_surf, self._bar_alpha)\n\n    def pump(self) -> None:\n        \"\"\"Non-blocking message pump for this thread's queue.\"\"\"\n        ct, wt = self._ct, self._wt\n\n        class MSG(ctypes.Structure):\n            _fields_ = [(\"hwnd\", wt.HWND), (\"message\", wt.UINT),\n                        (\"wParam\", wt.WPARAM), (\"lParam\", wt.LPARAM),\n                        (\"time\", wt.DWORD), (\"pt\", wt.POINT)]\n\n        msg = MSG()\n        while self.user32.PeekMessageW(ct.byref(msg), None, 0, 0,\n                                       self.PM_REMOVE):\n            self.user32.TranslateMessage(ct.byref(msg))\n            self.user32.DispatchMessageW(ct.byref(msg))\n\n\n# --- indicator backend -----------------------------------------------------------\n#\n# The CUA-mechanism indicator (owner directive 2026-10-06): the same motion\n# language as Cua Driver's agent cursor - speed-profile glide with a\n# spring-damper settle, a click pulse, a speech-style badge pill with delivery\n# and target chips - rendered in AutoSkill's own palette (teal #1A8E88 cursor,\n# the shared bar state vocabulary). Principle re-implementation per the\n# project's C1-C8 transfer rules; no CUA code.\n#\n# One moving layered window (not CUA's full-desktop surface - Python renders\n# a 1920x1080 canvas far too slowly) hosts cursor + pill + chips together, so\n# UpdateLayeredWindow moves and paints atomically and the composite never\n# tears. Everything is drawn per frame in PIL only while animating; a settled\n# indicator stops painting entirely.\n\nIND_W, IND_H = 300, 180            # moving window; cursor anchored at (70, 44)\nIND_ANCHOR = (70, 44)\nIND_SPRING = 0.72                  # cua-driver render_state.rs default\nIND_SPRING_K = IND_SPRING * 400.0  # 288 — spring constant\nIND_SPRING_C = IND_SPRING * 20.0   # 14.4 — damping\nIND_SETTLE_O = 0.3                 # px — settled when offset and velocity die\nIND_SETTLE_V = 2.0\nIND_PULSE_S = 0.25                 # click pulse duration\nIND_ARROW_UNITS = (                # cua-driver theme geometry, 128-unit canvas\n    (55, 30), (43, 41), (64, 98), (77, 99), (86, 79), (95, 70), (108, 63),\n    (107, 50))\nIND_HOTSPOT = (55, 30)\nIND_ARROW_PX = 42                  # display footprint\nIND_PILL_MAX_W, IND_PILL_H = 188, 28\nIND_PILL_GAP = 14                  # below the cursor tip\nIND_CHIP = 18                      # chip square\nIND_CHIP_GAP = 4\n\nIND_ENABLED = os.environ.get(\"AUTOSKILL_INDICATOR\", \"on\").strip().lower() not in (\n    \"off\", \"0\", \"false\", \"no\", \"disabled\")\n\n\ndef _arrow_polygon(scale: float) -> list[tuple[float, float]]:\n    \"\"\"The CUA arrow path normalised on its hotspot and scaled to pixels.\"\"\"\n    hx, hy = IND_HOTSPOT\n    return [((px - hx) * scale, (py - hy) * scale)\n            for px, py in IND_ARROW_UNITS]\n\n\nclass IndicatorBackend(Win32Backend):\n    \"\"\"The owner's 2026-10-07 composition: everything the previous renderer\n    showed — the cursor marker, the green edge-glow flash, the top status\n    box (all inherited from Win32Backend, byte-for-byte) — PLUS the\n    CUA-mechanism pointer: the CUA arrow geometry tinted AutoSkill teal, a\n    spring-damper glide-and-settle, a click pulse ring, and a speech badge\n    pill with delivery/target chips, drawn on a fourth layered window that\n    moves with the pointer (atomic move+paint via UpdateLayeredWindow).\n\n    The indicator window reuses the proven AutoskillAgentOverlay window\n    class (one class backs many windows), created and shown through the\n    same code paths the old backend uses in the daemon today.\n    \"\"\"\n\n    def __init__(self) -> None:\n        super().__init__()\n        self._i_hwnd = 0\n        self._i_surf: tuple | None = None\n        self._i_img: Any = None\n        self._i_font: Any = None\n        self._i_on = False\n        self._i_alpha = float(REST_ALPHA)\n        self._i_presented = False\n        # commanded position and the spring-chasing rendered offset within\n        # the moving window — the chase is the CUA glide-and-settle feel.\n        self._icx = self._icy = 0.0\n        self._isx = self._isy = 0.0\n        self._ivx = self._ivy = 0.0\n        self._heading = 0.0\n        self._pulse_t = -1.0\n        self._halo_t = -1.0\n        self._pill_hold = 0.0\n        self._pill_alpha = 0.0\n        self._pill_text = \"\"\n        self._pill_state = \"acting\"\n        self._chips: dict = {}\n        self._last_tick = 0.0\n        self._dirty = False\n        self._wx = 0\n        self._wy = 0\n\n    # -- lifecycle --------------------------------------------------------------\n\n    def start(self) -> None:\n        super().start()                     # cursor ring, glow, bar windows\n        from PIL import Image\n        left, top, right, bottom = self.virtual_screen()\n        self._screen = (left, top, right, bottom)\n        self._wx, self._wy = (left + right) // 2, (top + bottom) // 2\n        self._i_hwnd = self._make_window(IND_W, IND_H)\n        # Distinct title so tooling can tell the indicator window apart.\n        self.user32.SetWindowTextW(self._i_hwnd, \"AutoskillIndicator\")\n        if os.environ.get(\"AUTOSKILL_INDICATOR_CAPTURE\", \"\").strip().lower() in (\n                \"1\", \"true\", \"yes\", \"on\"):\n            # Debug aid: keep the indicator inside our own screen recordings\n            # so failed test cycles can be reviewed on video.\n            try:\n                self._display_affinity(self._i_hwnd, 0)   # WDA_NONE\n            except Exception:\n                pass\n        self._icx = self._icy = (left + right) / 2.0\n        self._i_img = Image.new(\"RGBA\", (IND_W, IND_H), (0, 0, 0, 0))\n        self._i_surf = self._new_surface(self._i_hwnd, IND_W, IND_H)\n        self._i_font = self._load_font(12)\n        self._dirty = True\n\n    def stop(self) -> None:\n        try:\n            if self._i_hwnd:\n                self.user32.DestroyWindow(self._i_hwnd)\n                self._i_hwnd = 0\n            if self._i_surf is not None:\n                self.gdi32.DeleteObject(self._i_surf[1])\n                self.gdi32.DeleteDC(self._i_surf[0])\n                self._i_surf = None\n        except Exception:\n            pass\n        super().stop()\n\n    def _load_font(self, size: int) -> Any:\n        from PIL import ImageFont\n        for name in (\"segoeui.ttf\", \"SegoeUI.ttf\", \"arial.ttf\"):\n            try:\n                return ImageFont.truetype(r\"C:\\Windows\\Fonts\" + \"\\\\\" + name, size)\n            except Exception:\n                continue\n        return ImageFont.load_default()\n\n    # -- duck-type surface: old visuals first, pointer mirrors -------------------\n\n    def place_cursor(self, x: float, y: float) -> None:\n        super().place_cursor(x, y)          # the familiar marker window\n        self._icx, self._icy = float(x), float(y)\n        self._dirty = True\n\n    def show_cursor(self, on: bool) -> None:\n        # Once the pointer has presented successfully, the small marker is\n        # redundant — but until then (and whenever the pointer is off) the\n        # old cursor keeps the tool visible, fail-open.\n        if on and self._i_presented and self._i_on:\n            return                          # keep marker hidden under pointer\n        super().show_cursor(on)\n        self._i_on = bool(on)\n        if on:\n            self.user32.ShowWindow(self._i_hwnd, self.SW_SHOWNA)\n            self._dirty = True\n\n    def set_cursor_alpha(self, alpha: int) -> None:\n        self._i_alpha = float(max(0, min(255, int(alpha))))\n        self._dirty = True\n        if not (self._i_presented and self._i_on):\n            super().set_cursor_alpha(alpha)\n\n    def show_glow(self, on: bool) -> None:\n        super().show_glow(on)               # the green edge flash, as before\n        if on:\n            self._halo_t = 0.0\n            self._dirty = True\n\n    def set_glow_alpha(self, alpha: int) -> None:\n        super().set_glow_alpha(alpha)       # the core drives the flash fade\n\n    def show_bar(self, on: bool) -> None:\n        super().show_bar(on)                # the top status box, as before\n        if not on:\n            self._pill_alpha = 0.0\n        self._dirty = True\n\n    def set_bar(self, text: str, state: str) -> None:\n        super().set_bar(text, state)\n        state = state if state in STATE_COLORS else \"acting\"\n        if text:\n            self._pill_text = str(text)\n        self._pill_state = state\n        self._pill_hold = 2.0\n        self._show_indicator()\n        self._dirty = True\n\n    def set_bar_alpha(self, alpha: int) -> None:\n        super().set_bar_alpha(alpha)\n\n    # -- semantic narration ------------------------------------------------------\n\n    def _show_indicator(self) -> None:\n        \"\"\"Ensure the pointer window is on screen (narration-only flows -\n        browser verbs - never trigger a desktop MOVE).\"\"\"\n        if self._i_hwnd and not self._i_on:\n            self._i_on = True\n            self.user32.ShowWindow(self._i_hwnd, self.SW_SHOWNA)\n            self._dirty = True\n\n    def note_pulse(self) -> None:\n        self._pulse_t = 0.0\n        self._dirty = True\n\n    def note_action(self, phase: str, action: str = \"\", target: str = \"\",\n                    label: str = \"\", delivery: str = \"\",\n                    outcome: str = \"\", effect: str = \"\") -> None:\n        if phase == \"begin\":\n            self._chips = {\"delivery\": delivery or \"background\",\n                           \"target\": target or \"desktop\",\n                           \"action\": action}\n            if label:\n                self._pill_text = str(label)[:28]\n            self._pill_hold = 2.0\n            self._show_indicator()\n        elif phase == \"end\":\n            self._chips[\"outcome\"] = outcome or \"ok\"\n            self._pill_state = \"done\" if outcome == \"ok\" else \"stuck\"\n            self._pill_hold = 0.4\n            self._show_indicator()   # an end-only flow must still surface\n        self._dirty = True\n\n    # -- render loop ---------------------------------------------------------------\n\n    def pump(self) -> None:\n        super().pump()                      # old windows' message pump\n        if self._i_on or self._dirty:\n            self._animate()\n            if self._dirty:\n                self._paint()\n\n    def _animate(self) -> None:\n        now = time.monotonic()\n        dt = min(0.05, max(0.001, now - (self._last_tick or now)))\n        self._last_tick = now\n        left, top, right, bottom = self._screen\n        wx = max(left, min(right - IND_W, int(self._icx) - IND_ANCHOR[0]))\n        wy = max(top, min(bottom - IND_H, int(self._icy) - IND_ANCHOR[1]))\n        self._wx, self._wy = wx, wy\n        tx = self._icx - wx\n        ty = self._icy - wy\n        dx, dy = tx - self._isx, ty - self._isy\n        if (dx * dx + dy * dy) > 0.25:\n            self._heading = math.atan2(dy, dx)\n        for _ in range(4):                  # cua-driver spring constants\n            sdt = dt / 4.0\n            ax = IND_SPRING_K * dx - IND_SPRING_C * self._ivx\n            ay = IND_SPRING_K * dy - IND_SPRING_C * self._ivy\n            self._ivx += ax * sdt\n            self._ivy += ay * sdt\n            self._isx += self._ivx * sdt\n            self._isy += self._ivy * sdt\n            dx, dy = tx - self._isx, ty - self._isy\n        if (abs(dx) < IND_SETTLE_O and abs(dy) < IND_SETTLE_O\n                and abs(self._ivx) < IND_SETTLE_V\n                and abs(self._ivy) < IND_SETTLE_V):\n            self._isx, self._isy = tx, ty\n            self._ivx = self._ivy = 0.0\n        if self._pulse_t >= 0.0:\n            self._pulse_t += dt\n            if self._pulse_t > IND_PULSE_S + 0.2:\n                self._pulse_t = -1.0\n        if self._halo_t >= 0.0:\n            self._halo_t += dt\n            if self._halo_t > 0.6:\n                self._halo_t = -1.0\n        if self._pill_hold > 0.0:\n            self._pill_hold -= dt\n            self._pill_alpha = min(255.0, self._pill_alpha + 900 * dt)\n        elif self._pill_alpha > 0.0:\n            self._pill_alpha = max(0.0, self._pill_alpha - 500 * dt)\n        moving = (abs(self._ivx) + abs(self._ivy)) > 0.5\n        self._dirty = bool(moving or self._pulse_t >= 0.0\n                           or self._halo_t >= 0.0 or self._pill_alpha > 0.0\n                           or self._dirty)\n\n    def _paint(self) -> None:\n        from PIL import ImageDraw\n        self._dirty = False\n        try:\n            self._paint_body(ImageDraw)\n        except Exception as exc:                  # temporary diagnostic\n            raise\n\n    def _paint_body(self, ImageDraw: Any) -> None:\n        img = self._i_img\n        img.paste((0, 0, 0, 0), (0, 0, IND_W, IND_H))\n        d = ImageDraw.Draw(img)\n        alpha = self._i_alpha / 255.0\n        ax, ay = IND_ANCHOR\n        bob_t = (time.monotonic() % 4.0) / 4.0 * 2 * math.pi\n        cx = ax + self._isx + 5 * math.sin(bob_t)\n        cy = ay + self._isy + 6 * math.cos(bob_t) - 5\n        rot = -math.degrees(self._heading) - 45.0 + 2.5 * math.cos(bob_t)\n        if self._halo_t >= 0.0:\n            frac = self._halo_t / 0.6\n            for step in range(3, 0, -1):\n                r = 20 + step * 8 * (0.5 + frac)\n                a = int(70 * (1.0 - frac) * alpha / step)\n                if a > 0:\n                    d.ellipse([cx - r, cy - r, cx + r, cy + r],\n                              outline=(*_rgb(GLOW_BGR), a), width=6)\n        if self._pulse_t >= 0.0:\n            frac = min(1.0, self._pulse_t / IND_PULSE_S)\n            radius = 10 + frac * 18\n            ring_a = int(220 * (1.0 - frac) * alpha)\n            if ring_a > 0:\n                d.ellipse([cx - radius, cy - radius, cx + radius, cy + radius],\n                          outline=(*_rgb(CURSOR_BGR), ring_a), width=3)\n        scale = IND_ARROW_PX / 128.0\n        rad = math.radians(rot)\n        poly = []\n        for px, py in _arrow_polygon(scale):\n            rx_ = px * math.cos(rad) - py * math.sin(rad)\n            ry_ = px * math.sin(rad) + py * math.cos(rad)\n            poly.append((cx + rx_, cy + ry_))\n        a_fill = int(255 * alpha)\n        d.polygon(poly, fill=(*_rgb(CURSOR_BGR), a_fill),\n                  outline=(255, 255, 255, a_fill))\n        if self._pill_alpha > 4 and (self._pill_text or self._chips):\n            self._draw_pill(d, cx, cy, int(self._pill_alpha * alpha))\n        self._present(img)\n\n    def _draw_pill(self, d: Any, cx: float, cy: float, alpha: int) -> None:\n        text = (self._pill_text or \"\")[:28]\n        try:\n            tw = d.textlength(text, font=self._i_font)\n        except Exception:\n            tw = len(text) * 7\n        pill_w = int(min(IND_PILL_MAX_W,\n                         2 * 10 + tw + 2 * (IND_CHIP + IND_CHIP_GAP) + 14))\n        px = int(cx - pill_w / 2)\n        py = int(cy + IND_PILL_GAP)\n        h = IND_PILL_H\n        bg = (*_rgb(BAR_BG), min(245, alpha))\n        d.rounded_rectangle([px, py, px + pill_w, py + h], radius=h // 2,\n                            fill=bg, outline=(*_rgb(CURSOR_BGR), alpha),\n                            width=1)\n        state_rgb = _rgb(STATE_COLORS.get(self._pill_state, DESKTOP_GREEN))\n        d.ellipse([px + 8, py + h // 2 - 4, px + 16, py + h // 2 + 4],\n                  fill=(*state_rgb, alpha))\n        if text:\n            d.text((px + 22, py + h // 2 - 7), text,\n                   fill=(*_rgb(BAR_TEXT), alpha), font=self._i_font)\n        gx = px + pill_w - 10 - 2 * (IND_CHIP + IND_CHIP_GAP)\n        delivery = self._chips.get(\"delivery\", \"background\")\n        self._chip(d, gx, py + (h - IND_CHIP) // 2,\n                   glyph=(\"windows\" if delivery == \"foreground\" else \"stack\"),\n                   filled=True, alpha=alpha)\n        target = self._chips.get(\"target\", \"desktop\")\n        self._chip(d, gx + IND_CHIP + IND_CHIP_GAP, py + (h - IND_CHIP) // 2,\n                   glyph=(\"globe\" if target == \"browser\" else \"monitor\"),\n                   filled=False, alpha=alpha)\n\n    def _chip(self, d: Any, x: int, y: int, glyph: str, filled: bool,\n              alpha: int) -> None:\n        fill_rgb = _rgb(CURSOR_BGR)\n        if filled:\n            d.rounded_rectangle([x, y, x + IND_CHIP, y + IND_CHIP], radius=5,\n                                fill=(*fill_rgb, int(alpha * 0.86)),\n                                outline=(255, 255, 255, int(alpha * 0.72)),\n                                width=1)\n            stroke = (255, 255, 255, int(alpha * 0.93))\n        else:\n            d.rounded_rectangle([x, y, x + IND_CHIP, y + IND_CHIP], radius=5,\n                                fill=(255, 255, 255, int(alpha * 0.09)),\n                                outline=(255, 255, 255, int(alpha * 0.42)),\n                                width=1)\n            stroke = (255, 255, 255, int(alpha * 0.93))\n        cx, cy = x + IND_CHIP / 2, y + IND_CHIP / 2\n        w = 1\n        if glyph == \"stack\":\n            d.rounded_rectangle([cx - 6, cy - 6, cx - 0.5, cy - 0.5], radius=1,\n                                outline=stroke, width=w)\n            d.rounded_rectangle([cx + 0.5, cy + 0.5, cx + 6, cy + 6], radius=1,\n                                outline=stroke, width=w)\n        elif glyph == \"windows\":\n            d.rounded_rectangle([cx - 5, cy - 4.5, cx + 5, cy + 4.5], radius=1,\n                                outline=stroke, width=w)\n            d.line([cx - 5, cy - 2, cx + 5, cy - 2], fill=stroke, width=w)\n        elif glyph == \"monitor\":\n            d.rounded_rectangle([cx - 5, cy - 4, cx + 5, cy + 2], radius=1,\n                                outline=stroke, width=w)\n            d.line([cx, cy + 2, cx, cy + 4], fill=stroke, width=w)\n            d.line([cx - 3, cy + 4, cx + 3, cy + 4], fill=stroke, width=w)\n        elif glyph == \"globe\":\n            d.ellipse([cx - 5, cy - 5, cx + 5, cy + 5], outline=stroke, width=w)\n            d.line([cx - 5, cy, cx + 5, cy], fill=stroke, width=w)\n            d.line([cx, cy - 5, cx, cy + 5], fill=stroke, width=w)\n\n    def _present(self, img: Any) -> None:\n        \"\"\"Copy the frame into the indicator DIB, then move and paint the\n        window in one atomic UpdateLayeredWindow call.\"\"\"\n        import ctypes\n        import ctypes.wintypes as wt\n        if self._i_surf is None:\n            return\n        raw = img.tobytes(\"raw\", \"RGBA\")\n        bgra = bytearray(len(raw))\n        bgra[0::4], bgra[1::4], bgra[2::4], bgra[3::4] = (\n            raw[2::4], raw[1::4], raw[0::4], raw[3::4])\n        for i in range(0, len(bgra), 4):\n            a8 = bgra[i + 3]\n            if a8 < 255:\n                bgra[i] = bgra[i] * a8 // 255\n                bgra[i + 1] = bgra[i + 1] * a8 // 255\n                bgra[i + 2] = bgra[i + 2] * a8 // 255\n        buf = self._i_surf[3]\n        buf[:] = bgra\n\n        class BLENDF(ctypes.Structure):\n            _fields_ = [(\"BlendOp\", ctypes.c_byte),\n                        (\"BlendFlags\", ctypes.c_byte),\n                        (\"SourceConstantAlpha\", ctypes.c_byte),\n                        (\"AlphaFormat\", ctypes.c_byte)]\n        blend = BLENDF()\n        blend.BlendOp = self.AC_SRC_OVER\n        blend.SourceConstantAlpha = 255\n        blend.AlphaFormat = self.AC_SRC_ALPHA\n        ppt = wt.POINT(self._wx, self._wy)\n        psrc = wt.POINT(0, 0)\n        ok = self.user32.UpdateLayeredWindow(\n            self._i_hwnd, None, ctypes.byref(ppt), None,\n            self._i_surf[0], ctypes.byref(psrc), 0,\n            ctypes.byref(blend), self.ULW_ALPHA)\n        if ok:\n            self._i_presented = True\n\n\ndef _rgb(bgr: tuple) -> tuple:\n    \"\"\"BGR constant -> PIL RGB.\"\"\"\n    return (bgr[2], bgr[1], bgr[0])\n\n\n# --- native companion backend --------------------------------------------------\n#\n# The WPF companion (native/overlay/autoskill-overlay.exe, C# — cua-driver's\n# own Windows reference language) renders the same cursor/glow/bar with\n# GPU-composited 60 fps springs. This backend is a translator: the overlay\n# core keeps its own animation state (harmless), and semantic events are\n# forwarded as JSON lines on the companion's stdin. Per-frame fades are\n# dropped — the companion animates those itself. If the exe is missing or\n# dies, _default() falls back to the pure-Python Win32Backend: fail-open.\n\nclass NativeBackend:\n    \"\"\"Backend talking to the WPF overlay companion over stdin JSON lines.\"\"\"\n\n    EXE = (Path(__file__).resolve().parents[3]\n           / \"native\" / \"overlay\" / \"autoskill-overlay.exe\")\n    MOVE_EVERY_S = 0.06             # forward at most ~16 positions/second\n    MOVE_MIN_PX = 24                # ...or when the hop is clearly a new target\n\n    def __init__(self, cmd: list[str] | None = None) -> None:\n        self._cmd = cmd\n        self._proc: Any = None\n        self._last_move = 0.0\n        self._last_xy: tuple[float, float] | None = None\n        self._bar_on = False\n\n    def available(self) -> bool:\n        if self._cmd is None and not self.EXE.is_file():\n            from ..resources import asset\n            try:\n                self.EXE = asset(\"native/overlay/autoskill-overlay.exe\")\n            except FileNotFoundError:\n                return False\n        return self._cmd is not None or self.EXE.is_file()\n\n    # -- lifecycle --------------------------------------------------------------\n\n    def start(self) -> None:\n        import subprocess\n        cmd = self._cmd or [str(self.EXE)]\n        if self._cmd is None and not self.EXE.is_file():\n            raise OSError(\"native overlay companion not built\")\n        flags = getattr(subprocess, \"CREATE_NO_WINDOW\", 0)\n        self._proc = subprocess.Popen(\n            cmd, stdin=subprocess.PIPE,\n            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,\n            creationflags=flags)\n        self._send({\"op\": \"bitmap\", \"data\": base64.b64encode(cursor_pixels()).decode(\"ascii\")})\n\n    def stop(self) -> None:\n        try:\n            self._send({\"op\": \"quit\"})\n        except Exception:\n            pass\n        proc = self._proc\n        if proc is not None:\n            try:\n                if proc.stdin:\n                    proc.stdin.close()      # EOF: the child exits cleanly\n            except Exception:\n                pass\n            try:\n                proc.wait(timeout=2.0)\n            except Exception:\n                try:\n                    proc.kill()\n                    proc.wait(timeout=2.0)\n                except Exception:\n                    pass\n        self._proc = None\n\n    def _send(self, obj: dict[str, Any]) -> None:\n        try:\n            proc = self._proc\n            if proc is None or proc.poll() is not None:\n                return\n            line = json.dumps(obj, ensure_ascii=False) + \"\\n\"\n            proc.stdin.write(line.encode(\"utf-8\"))\n            proc.stdin.flush()\n        except Exception:\n            pass                         # fail-open, always\n\n    # -- operations (same interface as Win32Backend) ------------------------------\n\n    def virtual_screen(self) -> tuple[int, int, int, int]:\n        import ctypes\n        u = ctypes.windll.user32\n        left, top = u.GetSystemMetrics(76), u.GetSystemMetrics(77)\n        return left, top, left + u.GetSystemMetrics(78), \\\n            top + u.GetSystemMetrics(79)\n\n    def place_cursor(self, x: float, y: float) -> None:\n        self._send({\"op\": \"move\", \"x\": int(x), \"y\": int(y)})\n\n    def pin_above(self, hwnd: int) -> None:\n        \"\"\"b4of item 5: GA_ROOT normalization at the sender, exactly CUA's\n        pin_overlay_above (impl_.rs:17-30; the null-root fallback :21-25\n        keeps the child when GetAncestor fails).\"\"\"\n        import ctypes\n        root = ctypes.windll.user32.GetAncestor(int(hwnd), 2)  # GA_ROOT\n        self._send({\"op\": \"pin\", \"hwnd\": int(root or hwnd)})\n\n    def show_cursor(self, on: bool) -> None:\n        self._send({\"op\": \"cursor\", \"on\": bool(on)})\n\n    def set_cursor_alpha(self, alpha: int) -> None:\n        self._send({\"op\": \"alpha\", \"value\": max(0, min(255, alpha)) / 255})\n\n    def show_glow(self, on: bool) -> None:\n        if on:\n            self._send({\"op\": \"glow\"})   # flash; decay is native\n\n    def set_glow_alpha(self, alpha: int) -> None:\n        pass\n\n    def show_bar(self, on: bool) -> None:\n        self._bar_on = bool(on)\n        if not on:\n            self._send({\"op\": \"hidebar\"})\n\n    def set_bar(self, text: str, state: str) -> None:\n        if self._bar_on:\n            self._send({\"op\": \"say\", \"text\": text, \"state\": state})\n\n    def set_bar_alpha(self, alpha: int) -> None:\n        pass\n\n    def pump(self) -> None:\n        pass                             # the companion owns its message loop\n\n\nclass NativeIndicatorBackend(NativeBackend):\n    \"\"\"The rebuilt CUA pointer (owner directive 2026-10-07; stage-1 sync\n    2026-10-09), rendered by the same WPF companion. The exe owns everything\n    CUA-faithful - motion, glide arrival (reported on stdout), visibility,\n    idle lifecycle and capture exclusion; Python forwards one id-tagged\n    target per action and waits for the renderer's arrival before input\n    dispatches. The legacy 32px marker ops are suppressed. Fail-open exactly\n    like NativeBackend (dead child -> _default() rebuilds).\"\"\"\n\n    owns_glide = True       # the exe plans and reports the glide\n    owns_idle = True        # the exe owns the idle lifecycle (single clock)\n    owns_capture = True     # WDA_EXCLUDEFROMCAPTURE; never hide for captures\n    ARRIVAL_CAP_S = 2.0     # backstop only - the normal path is the event\n\n    def __init__(self, cmd: list[str] | None = None) -> None:\n        super().__init__(cmd)\n        self._move_id = 0\n        self._await_id = -1\n        self._arrived: set[int] = set()\n        self._cv = threading.Condition()\n        self._placed = False    # perf1: has this renderer's pointer been placed since it started or was hidden?\n\n    def start(self) -> None:\n        # Same spawn as the parent, but stdout is the renderer's event\n        # channel (arrival reports) instead of /dev/null.\n        import subprocess\n        self._placed = False\n        cmd = self._cmd or [str(self.EXE)]\n        if self._cmd is None and not self.EXE.is_file():\n            raise OSError(\"native overlay companion not built\")\n        flags = getattr(subprocess, \"CREATE_NO_WINDOW\", 0)\n        self._proc = subprocess.Popen(\n            cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,\n            stderr=subprocess.DEVNULL, creationflags=flags)\n        self._send({\"op\": \"bitmap\", \"data\": base64.b64encode(cursor_pixels()).decode(\"ascii\")})\n        if self._proc.stdout is not None:\n            threading.Thread(target=self._read_loop, daemon=True,\n                             name=\"autoskill-driver-events\").start()\n\n    def _read_loop(self) -> None:\n        \"\"\"The renderer's event channel: arrival reports gate input.\"\"\"\n        try:\n            for line in self._proc.stdout:\n                try:\n                    ev = json.loads(line)\n                except Exception:\n                    continue\n                if isinstance(ev, dict) and ev.get(\"ev\") == \"arrived\":\n                    with self._cv:\n                        try:\n                            self._arrived.add(int(ev.get(\"id\", -1)))\n                        except (TypeError, ValueError):\n                            pass\n                        self._cv.notify_all()\n        except Exception:\n            pass                         # fail-open: cap timers take over\n\n    def begin_move(self) -> int:\n        \"\"\"Allocate the move id on the calling thread so the arrival waiter\n        is registered before the command is queued (CUA race rule).\"\"\"\n        self._move_id += 1\n        self._await_id = self._move_id\n        return self._move_id\n\n    def place_cursor(self, x: float, y: float,\n                     move_id: int | None = None) -> None:\n        mid = self._move_id if move_id is None else move_id\n        if not self._placed:\n            # perf1: CUA's first use snaps to the target and skips the glide wait (impl_.rs:287-289, :313-320).\n            self._placed = True\n            self._send({\"op\": \"psnap\", \"x\": int(x), \"y\": int(y)})\n            self._send({\"op\": \"pshow\", \"on\": True})\n            with self._cv:\n                self._arrived.add(int(mid))\n                self._cv.notify_all()\n            return\n        self._send({\"op\": \"pmove\", \"x\": int(x), \"y\": int(y), \"id\": int(mid)})\n\n    def wait_arrival(self, timeout: float | None = None) -> bool:\n        \"\"\"Wait for the renderer's true arrival of the registered move.\n        Returns False on timeout - the cap is a backstop, never the normal\n        path (CUA: input follows the arrow's arrival).\"\"\"\n        if self._proc is None or self._proc.poll() is not None:\n            return False\n        cap = self.ARRIVAL_CAP_S if timeout is None else max(0.0, timeout)\n        deadline = time.monotonic() + cap\n        with self._cv:\n            while self._await_id not in self._arrived:\n                remaining = deadline - time.monotonic()\n                if remaining <= 0:\n                    return False\n                self._cv.wait(remaining)\n        return True\n\n    def pulse(self, x: float | None = None, y: float | None = None) -> None:\n        payload: dict[str, Any] = {\"op\": \"ppulse\"}\n        if x is not None and y is not None:\n            payload[\"x\"], payload[\"y\"] = int(x), int(y)\n        self._send(payload)\n\n    def show_cursor(self, on: bool) -> None:\n        if not on:\n            return                       # the renderer owns idle/hide\n        self._send({\"op\": \"pshow\", \"on\": True})\n\n    def pointer_hide(self) -> None:\n        \"\"\"The companion's own hide op (AgentOverlay.cs:1389). Like CUA's removed session cursor, the next\n        placement starts over with a snap.\"\"\"\n        self._send({\"op\": \"hide\"})\n        self._placed = False\n\n    def set_cursor_alpha(self, alpha: int) -> None:\n        pass                         # the exe owns pointer opacity (CUA idle)\n\n    def note_pulse(self) -> None:\n        pass                         # pulses carry coordinates (see pulse())\n\n    def note_action(self, phase: str = \"\", action: str = \"\", target: str = \"\",\n                    label: str = \"\", delivery: str = \"\",\n                    outcome: str = \"\", effect: str = \"\") -> None:\n        self._send({\"op\": \"pbadge\", \"phase\": phase, \"action\": action,\n                    \"target\": target, \"label\": label, \"delivery\": delivery,\n                    \"outcome\": outcome, \"effect\": effect})\n\n\ndef _make_backend() -> Any:\n    \"\"\"Pick the renderer: AUTOSKILL_OVERLAY=native|win32 forces a backend;\n    AUTOSKILL_INDICATOR=off (default on) selects the CUA-mechanism\n    indicator - the rebuilt native companion pointer when its exe is built,\n    the pure-Python IndicatorBackend otherwise; with the indicator off the\n    default prefers the native companion when built and falls back to the\n    pure-Python backend.\"\"\"\n    mode = os.environ.get(\"AUTOSKILL_OVERLAY\", \"on\").strip().lower()\n    if mode == \"win32\":\n        return Win32Backend()\n    if mode == \"native\":\n        return NativeBackend()\n    if IND_ENABLED and os.name == \"nt\":\n        nbi = NativeIndicatorBackend()\n        if nbi.available():\n            return nbi\n        return IndicatorBackend()\n    nb = NativeBackend()\n    return nb if nb.available() else Win32Backend()\n\n\n# --- overlay core --------------------------------------------------------------\n\n# Commands. Keep them plain tuples; the queue is the only cross-thread\n# channel, so there is no shared mutable state to lock.\n_MOVE = \"move\"\n_PULSE = \"pulse\"\n_GLOW = \"glow\"\n_SAY = \"say\"\n_ACTION = \"action\"\n_HIDE = \"hide\"\n_SHUTDOWN = \"shutdown\"\n\n\nclass AgentCursorOverlay:\n    \"\"\"Thread-owning overlay. All Win32 work happens on the worker thread;\n    callers only enqueue commands. Everything is fail-open.\"\"\"\n\n    def __init__(self, backend: Any | None = None) -> None:\n        self._backend: Any = backend if backend is not None else Win32Backend()\n        self._q: queue.Queue[tuple] = queue.Queue()\n        self._thread: threading.Thread | None = None\n        self._lock = threading.Lock()\n        self._started = threading.Event()\n        self._alive = False          # worker side: backend created OK\n        self._arrival = threading.Event()\n        self._arrival.set()\n\n        # Worker-side animation state (only _tick touches it).\n        self._cx = self._cy = 0.0\n        self._tx = self._ty = 0.0\n        self._cursor_visible = False\n        self._cursor_alpha = float(REST_ALPHA)\n        self._path: list = []\n        self._move_started = 0.0\n        self._path_index = 0\n        self._cursor_activity = 0.0\n        self._fade_check = 0.0\n        self._fading = False\n        self._glow_alpha = 0.0\n        self._glow_visible = False\n        self._bar_visible = False\n        self._bar_alpha = 0.0\n        self._bar_text = \"\"\n        self._bar_state = \"acting\"\n        self._last_activity = 0.0\n        self._shutdown = False\n\n    # -- lifecycle (calling thread) -------------------------------------------\n\n    def start(self) -> bool:\n        \"\"\"Start the worker thread once. Returns True if it came up.\"\"\"\n        with self._lock:\n            if self._thread is not None:\n                return self._alive\n            self._thread = threading.Thread(\n                target=self._run, name=\"autoskill-overlay\", daemon=True)\n            self._thread.start()\n        # Wait briefly for backend creation; if the machine cannot host the\n        # overlay, callers must not hang on it.\n        self._started.wait(timeout=2.0)\n        return self._alive\n\n    @property\n    def alive(self) -> bool:\n        return self._alive\n\n    # -- commands (calling thread; never raise, never block long) --------------\n\n    def move_to(self, x: int, y: int, *, wait: bool = True) -> None:\n        \"\"\"Glide the cursor to (x, y). With wait=True, block until it\n        arrives — for arrival-reporting backends (the native renderer) that\n        is the exe's true arrival event; otherwise the capped core-level\n        arrival, so a wedged overlay never delays real input.\"\"\"\n        waiter = getattr(self._backend, \"begin_move\", None)\n        mid = waiter() if waiter is not None else None\n        self._arrival.clear()\n        self._q.put((_MOVE, float(x), float(y), mid))\n        if wait:\n            ack = getattr(self._backend, \"wait_arrival\", None)\n            if ack is not None:\n                ack()                        # true arrival; cap is a backstop\n            else:\n                self._arrival.wait(timeout=ARRIVAL_WAIT_S)\n\n    def pin_above(self, hwnd: int) -> None:\n        \"\"\"b4o: pin the cursor window above the driven root. Routed\n        straight to the native backend (a pure z-order op, no frame\n        work); fail-open when the backend lacks it.\"\"\"\n        pin = getattr(self._backend, \"pin_above\", None)\n        if pin is not None:\n            pin(int(hwnd))\n\n    def pulse(self) -> None:\n        \"\"\"Record click activity; cuabot has no rendered click pulse.\"\"\"\n        self._q.put((_PULSE,))\n\n    def glow_flash(self) -> None:\n        \"\"\"Flash the translucent sky-blue border around the screen.\"\"\"\n        self._q.put((_GLOW,))\n\n    def hide(self) -> None:\n        self._q.put((_HIDE,))\n\n    def say(self, text: str, state: str = \"acting\") -> None:\n        \"\"\"Narrate the current step on the status bar. Empty text keeps the\n        previous text; the bar auto-hides after BAR_IDLE_S of silence.\"\"\"\n        self._q.put((_SAY, str(text or \"\"), str(state or \"acting\")))\n\n    def action(self, phase: str, action: str = \"\", target: str = \"\",\n               label: str = \"\", delivery: str = \"\", outcome: str = \"\",\n               effect: str = \"\") -> None:\n        \"\"\"Semantic narration event (indicator narrator): drives the\n        indicator's badge pill and delivery/target chips. Never raises.\"\"\"\n        self._q.put((_ACTION, {\"phase\": phase, \"action\": action,\n                               \"target\": target, \"label\": label,\n                               \"delivery\": delivery, \"outcome\": outcome,\n                               \"effect\": effect}))\n\n    def shutdown(self) -> None:\n        self._q.put((_SHUTDOWN,))\n        t = self._thread\n        if t is not None:\n            t.join(timeout=2.0)\n\n    # -- worker ----------------------------------------------------------------\n\n    def _run(self) -> None:\n        try:\n            try:\n                self._backend.start()\n                self._alive = True\n            except Exception:\n                self._alive = False      # fail-open: no overlay, no error\n                return                  # Do not orphan a failed worker forever.\n            finally:\n                self._started.set()\n            while not self._shutdown:\n                self._tick(TICK_S)\n        except Exception:\n            self._alive = False          # belt and braces: never propagate\n        finally:\n            self._alive = False\n            self._arrival.set()\n            self._started.set()\n            try:\n                self._backend.stop()\n            except Exception:\n                pass\n\n    def _tick(self, block_s: float) -> None:\n        \"\"\"One loop iteration: drain pending commands, animate one step,\n        pump the message queue. Tests drive this directly with a fake\n        backend and block_s=0 — no thread, no windows.\"\"\"\n        if not self._alive:\n            # Still drain the queue so producers never fill it; do nothing.\n            try:\n                while True:\n                    cmd = self._q.get(block=bool(block_s),\n                                      timeout=block_s or 0)\n                    if cmd[0] == _SHUTDOWN:\n                        self._shutdown = True\n            except queue.Empty:\n                pass\n            try:\n                self._backend.pump()\n            except Exception:\n                pass\n            return\n\n        try:\n            cmd = self._q.get(timeout=max(block_s, 0.0))\n            self._handle(cmd)\n        except queue.Empty:\n            pass\n        # Drain anything that piled up behind the first command.\n        while True:\n            try:\n                self._handle(self._q.get_nowait())\n            except queue.Empty:\n                break\n\n        self._animate(TICK_S)\n        try:\n            self._backend.pump()\n        except Exception:\n            pass\n\n    def _handle(self, cmd: tuple) -> None:\n        kind = cmd[0]\n        self._last_activity = time.monotonic()\n        try:\n            if kind == _MOVE:\n                self._tx, self._ty = cmd[1], cmd[2]\n                self._cursor_activity = time.monotonic()\n                self._fading = False\n                if getattr(self._backend, \"owns_glide\", False):\n                    # The renderer plans and reports the glide (stage 1):\n                    # one raw target, no Python phantom path, no waypoints.\n                    self._backend.place_cursor(self._tx, self._ty,\n                                               move_id=cmd[3])\n                    self._arrival.set()\n                    return\n                if not self._cursor_visible:\n                    angle = random.random() * 2 * math.pi\n                    self._cx = self._tx + math.cos(angle) * 128\n                    self._cy = self._ty + math.sin(angle) * 128\n                    self._cursor_alpha = 0.0\n                    self._backend.set_cursor_alpha(0)\n                    self._backend.place_cursor(self._cx, self._cy)\n                    self._set_cursor_visible(True)\n                self._path = generate_path((self._cx, self._cy), (self._tx, self._ty))\n                self._path_index = 0\n                self._move_started = time.monotonic()\n            elif kind == _PULSE:\n                # cuabot tracks clicks but draws no scale/ring/pulse effect.\n                self._cursor_activity = time.monotonic()\n                self._fading = False\n                if getattr(self._backend, \"owns_glide\", False):\n                    self._backend.pulse(self._tx, self._ty)   # anchored at target\n                    return\n                note = getattr(self._backend, \"note_pulse\", None)\n                if note is not None:\n                    note()               # the indicator backend draws a ring\n            elif kind == _GLOW:\n                self._glow_alpha = float(GLOW_ALPHA)\n                if not self._glow_visible:\n                    self._glow_visible = True\n                    self._backend.show_glow(True)\n                self._backend.set_glow_alpha(self._glow_alpha)\n            elif kind == _SAY:\n                text, state = cmd[1], cmd[2]\n                if text:\n                    self._bar_text = text\n                if state:\n                    self._bar_state = state\n                if not self._bar_visible:\n                    self._bar_visible = True\n                    self._bar_alpha = 0.0\n                    self._backend.show_bar(True)\n                self._backend.set_bar(self._bar_text, self._bar_state)\n            elif kind == _ACTION:\n                # Semantic narration from the indicator narrator (daemon\n                # EventBus subscriber). Old backends simply ignore it.\n                note = getattr(self._backend, \"note_action\", None)\n                if note is not None:\n                    note(**cmd[1])\n                self._cursor_activity = time.monotonic()\n                self._fading = False\n            elif kind == _HIDE:\n                self._path = []\n                self._cursor_alpha = 0.0\n                self._fading = False\n                self._arrival.set()\n                self._set_cursor_visible(False)\n                self._set_glow_visible(False)\n                self._set_bar_visible(False)\n                pointer_hide = getattr(self._backend, \"pointer_hide\", None)\n                if pointer_hide is not None:\n                    pointer_hide()       # a renderer that owns its pointer hides it itself\n            elif kind == _SHUTDOWN:\n                self._shutdown = True\n        except Exception:\n            pass                         # fail-open, always\n\n    def _set_cursor_visible(self, on: bool) -> None:\n        if self._cursor_visible != on:\n            self._cursor_visible = on\n            self._backend.show_cursor(on)\n\n    def _set_glow_visible(self, on: bool) -> None:\n        if self._glow_visible != on:\n            self._glow_visible = on\n            self._backend.show_glow(on)\n\n    def _set_bar_visible(self, on: bool) -> None:\n        if self._bar_visible != on:\n            self._bar_visible = on\n            self._backend.show_bar(on)\n\n    def _animate(self, dt: float) -> None:\n        \"\"\"Advance glide / pulse / glow / idle-fade by dt seconds.\"\"\"\n        try:\n            now = time.monotonic()\n            if self._cursor_visible and self._path:\n                progress = min(1.0, (now - self._move_started) / (GLIDE_MS / 1000))\n                index = int(progress * (len(self._path) - 1))\n                if index > self._path_index:\n                    self._path_index = index\n                    self._cx, self._cy = self._path[index]\n                    self._backend.place_cursor(self._cx, self._cy)\n                if progress >= 1:\n                    self._path = []\n                    self._arrival.set()\n            if now - self._fade_check >= 1:\n                self._fade_check = now\n                if self._cursor_visible and now - self._cursor_activity > IDLE_FADE_S:\n                    self._fading = True\n            if self._cursor_visible:\n                if self._fading:\n                    self._cursor_alpha = max(0.0, self._cursor_alpha - 255 * .05)\n                    if self._cursor_alpha == 0:\n                        self._set_cursor_visible(False)\n                        self._fading = False\n                elif self._cursor_alpha < 255:\n                    self._cursor_alpha = min(255.0, self._cursor_alpha + 255 * .1)\n                self._backend.set_cursor_alpha(self._cursor_alpha)\n\n            # Glow flash: decay to nothing, then hide the frame.\n            if self._glow_visible and self._glow_alpha > 0.0:\n                self._glow_alpha -= GLOW_DECAY_PER_S * dt\n                if self._glow_alpha <= 0.0:\n                    self._glow_alpha = 0.0\n                    self._set_glow_visible(False)\n                else:\n                    self._backend.set_glow_alpha(self._glow_alpha)\n\n            # Bar: settle in fast while active, fade out and hide after\n            # BAR_IDLE_S of silence.\n            if self._bar_visible and self._last_activity:\n                idle_for = time.monotonic() - self._last_activity\n                if idle_for > BAR_IDLE_S:\n                    self._bar_alpha -= BAR_FADE_OUT_PER_S * dt\n                    if self._bar_alpha <= 0.0:\n                        self._bar_alpha = 0.0\n                        self._set_bar_visible(False)\n                    else:\n                        self._backend.set_bar_alpha(self._bar_alpha)\n                elif self._bar_alpha < BAR_REST_ALPHA:\n                    self._bar_alpha = min(\n                        float(BAR_REST_ALPHA),\n                        self._bar_alpha + BAR_FADE_IN_PER_S * dt)\n                    self._backend.set_bar_alpha(self._bar_alpha)\n        except Exception:\n            pass                         # fail-open, always\n\n\n# --- module-level facade -------------------------------------------------------\n\n_overlay: AgentCursorOverlay | None = None\n_overlay_lock = threading.Lock()\n_overlay_failed = False\n\n\ndef is_enabled() -> bool:\n    return ENABLED\n\n\ndef _default() -> AgentCursorOverlay | None:\n    \"\"\"The process-wide overlay, started lazily. None when disabled or\n    when the backend could not start — callers treat both as 'no overlay'.\"\"\"\n    global _overlay, _overlay_failed\n    if not ENABLED or _overlay_failed:\n        return None\n    with _overlay_lock:\n        if _overlay is not None and isinstance(_overlay._backend, NativeBackend):\n            proc = _overlay._backend._proc\n            if proc is None or proc.poll() is not None:\n                _overlay.shutdown()\n                _overlay = AgentCursorOverlay(backend=_make_backend())\n                if not _overlay.start():\n                    _overlay_failed = True\n                    return None\n        if _overlay is None:\n            backend = _make_backend()\n            ov = AgentCursorOverlay(backend=backend)\n            if ov.start():\n                _overlay = ov\n            else:\n                ov.shutdown()\n                _overlay_failed = True\n                return None\n        return _overlay if _overlay.alive else None\n\n\ndef move_to(x: int, y: int, *, wait: bool = True) -> None:\n    try:\n        ov = _default()\n        if ov is not None:\n            ov.move_to(x, y, wait=wait)\n    except Exception:\n        pass\n\n\ndef aim(x: int, y: int) -> None:\n    \"\"\"Glide to (x, y), firing the glow flash if the agent is *starting*\n    to act (cursor currently idle/hidden) rather than mid-sequence.\"\"\"\n    try:\n        ov = _default()\n        if ov is None:\n            return\n        if not ov._cursor_visible:\n            ov.glow_flash()\n        ov.move_to(int(x), int(y))\n    except Exception:\n        pass\n\ndef pin_above(hwnd: int) -> None:\n    \"\"\"b4o (owner decision, handoff section 3 item 7): pin the overlay's\n    cursor window just above the driven window's ROOT, like CUA's cursor\n    (pin_overlay_above -> GA_ROOT). Fail-open like every overlay op.\"\"\"\n    try:\n        ov = _default()\n        if ov is not None:\n            ov.pin_above(int(hwnd))\n    except Exception:\n        pass\n\n\ndef pulse() -> None:\n    try:\n        ov = _default()\n        if ov is not None:\n            ov.pulse()\n    except Exception:\n        pass\n\n\ndef glow_flash() -> None:\n    try:\n        ov = _default()\n        if ov is not None:\n            ov.glow_flash()\n    except Exception:\n        pass\n\n\ndef say(text: str, state: str = \"acting\") -> None:\n    \"\"\"Narrate the current step on the status bar (empty text keeps the\n    previous one). One shared state vocabulary with the browser toolbar:\n    aiming / acting / verifying / done / stuck / approval.\"\"\"\n    try:\n        ov = _default()\n        if ov is not None:\n            ov.say(text, state)\n    except Exception:\n        pass\n\n\ndef action(phase: str, action: str = \"\", target: str = \"\", label: str = \"\",\n           delivery: str = \"\", outcome: str = \"\", effect: str = \"\") -> None:\n    \"\"\"Forward one semantic action event to the indicator (badge + chips).\n    Fail-open like every facade entry; surfaces without an indicator,\n    including the browser tool's own in-page bar, are untouched.\"\"\"\n    try:\n        ov = _default()\n        if ov is not None:\n            ov.action(phase=phase, action=action, target=target, label=label,\n                      delivery=delivery, outcome=outcome, effect=effect)\n    except Exception:\n        pass\n\n\ndef hide() -> None:\n    try:\n        ov = _overlay  # Hiding must not create a new renderer or window.\n        if ov is not None:\n            ov.hide()\n    except Exception:\n        pass\n\n\ndef warm() -> None:\n    \"\"\"Start the renderer with the daemon, off the caller's thread, so no action waits for its cold start\n    (CUA: overlay::run_on_thread at tool registration, platform-windows/src/lib.rs:148-151).\"\"\"\n    def run() -> None:\n        try:\n            _default()\n        except Exception:\n            pass                         # fail-open like every overlay op\n    threading.Thread(target=run, daemon=True, name=\"autoskill-overlay-warm\").start()\n\n\ndef release() -> None:\n    \"\"\"A session ended: hide its pointer and keep the renderer (CUA's session-end remove_cursor,\n    impl_.rs:10310-10325). A new session may retry a failed start.\"\"\"\n    global _overlay_failed\n    _overlay_failed = False\n    hide()\n\n\ndef shutdown() -> None:\n    global _overlay, _overlay_failed\n    try:\n        with _overlay_lock:\n            ov = _overlay\n            _overlay = None\n            _overlay_failed = False  # A new session may recover from startup failure.\n        if ov is not None:\n            ov.shutdown()\n    except Exception:\n        pass\n\n\natexit.register(shutdown)\n\n\n@contextmanager\ndef cue(x: int | None, y: int | None):\n    \"\"\"One action's worth of overlay feedback: glide to (x, y) on entry,\n    pulse on exit. The glow flash fires when the agent *starts* acting —\n    the first cue while the overlay is idle — not on every click.\n\n    Never raises, whatever happens.\n    \"\"\"\n    fired = False\n    try:\n        ov = _default() if x is not None and y is not None else None\n        if ov is not None:\n            fired = True\n            assert x is not None and y is not None\n            aim(int(x), int(y))\n    except Exception:\n        pass\n    try:\n        yield\n    finally:\n        if fired and ov is not None:\n            try:\n                ov.pulse()\n            except Exception:\n                pass\n\n\n@contextmanager\ndef hidden_for_capture():\n    \"\"\"Hide the overlay while autoskill screenshots its own screen.\n\n    The marker would otherwise photograph itself into every capture the\n    agent takes to observe its own work. Restores nothing explicitly —\n    the next cue re-shows the cursor — because a screenshot followed by an\n    action should show the marker at the *new* target, not the old one.\n    \"\"\"\n    ov = None\n    try:\n        ov = _overlay  # Capture never starts an indicator just to hide it.\n        if ov is not None and not getattr(ov._backend, \"owns_capture\", False):\n            # Native renderer: the window is already excluded from our\n            # captures (WDA_EXCLUDEFROMCAPTURE) — hiding it just makes the\n            # indicator blink between every screenshot (stage 1 fix).\n            ov.hide()\n            time.sleep(0.06)           # let DWM actually drop the window\n    except Exception:\n        pass\n    try:\n        yield\n    finally:\n        pass\n");
